import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { getServerSession } from '@/lib/auth';

const PUBLIC_PATHS = ['/login', '/register', '/api/auth'];

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  if (PUBLIC_PATHS.some(path => pathname.startsWith(path))) {
    return NextResponse.next();
  }

  const session = await getServerSession();
  if (!session) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('redirect', pathname);
    return NextResponse.redirect(loginUrl);
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico|.*\\.png$).*)'],
};
```

**Security decisions made:**
- No AWS credentials in client bundle — presigned URLs generated server-side after auth
- File validation (type/size) enforced server-side before presigning
- Ownership enforced via object key prefix (`uploads/{userId}/`) and DB `WHERE userId = session.user.id`
- RLS-ready Prisma schema with user-scoped queries
- HttpOnly Secure SameSite cookies for session, no localStorage tokens
- CSP-ready headers in next.config.js
- Structured logging (no user input interpolation)
- Exact dependency versions pinned
